        "names": {
          "zh": "咕嘎和 Doro · 植物大战僵尸 · 香蒲雨池",
          "en": "Guga & Doro · Plants vs. Zombies · Cattail Rainpool"
        },
        "kin": null,
        "decor": {
          "pals": [
            {
              "$dshAsset": 0
            },
            {
              "$dshAsset": 1
            },
            {
              "$dshAsset": 2
            },
            {
              "$dshAsset": 3
            }
          ],
          "phrases": {
            "zh": [
              [
                "doro～叶舟放轻一点，雨池就不晃啦。",
                "doro！这一片小叶子，也想去兜兜风。"
              ],
              [
                "doro？小水珠，先在碟子里歇一会儿。",
                "doro～香蒲看着呢，慢慢把船放下。"
              ],
              [
                "doro～叶面擦干，夜风就不凉啦。",
                "doro！今天的小航行，平安靠岸。"
              ],
              [
                "doro～小毛巾卷好，明天再来放船。",
                "doro！锅帽上的雨声，也收工啦。"
              ]
            ],
            "en": [
              [
                "Doro~ Gently. Keep our tiny pool still.",
                "Doro! Even a little leaf wants a boat ride."
              ],
              [
                "Doro? Little raindrops, rest in this saucer.",
                "Doro~ Cattail is watching. Lower the boat slowly."
              ],
              [
                "Doro~ Dry leaves stay cozy in the evening breeze.",
                "Doro! Our little voyage is safely ashore."
              ],
              [
                "Doro~ Towel rolled. More little voyages tomorrow.",
                "Doro! Even the rain on my pot has clocked out."
              ]
            ]
          },
          "wallpaperSize": "min(32vw, 460px, calc(68vh * var(--dsw-pack-wallpaper-ratio, 1)), max(250px, calc((100vw - 1160px) / 2 - 24px)))",
          "wallpaperPosition": "right 16px bottom 12px",
          "heroTranslate": "calc(-0.3 * min(32vw, 460px)) calc(-1 * min(6vh, 60px))",
          "heroMaxWidth": "calc(100vw - 280px - min(32vw, 460px) - 64px)"
        },
