          "phrases": {
            "zh": [
              [
                "阿狸：先喝杯茶，再听你的故事。"
              ],
              [
                "亚索：风也有停下来的时候。"
              ],
              [
                "艾瑞莉娅：此刻的宁静，值得守护。"
              ],
              [
                "阿卡丽：点心我先替你尝了。"
              ]
            ],
            "en": [
              [
                "Ahri: A cup of tea, then your story."
              ],
              [
                "Yasuo: Even the wind takes a pause."
              ],
              [
                "Irelia: This quiet moment is worth protecting."
              ],
              [
                "Akali: I already checked the snacks."
              ]
            ]
          },
